// One shared floor selector and camera for the complete transport complex.
let mallSelected=null,mallReady=false,mallError=false;
const mallFloors=[],mallNames={},stationRenderer=render;
// The north edge now includes the bus-terminal volume, not just the retail outline.
// Approximate registration, not a survey or proof of floor-to-floor connections.
const mallMatrix='matrix(.4532 .0992 -.08654 .4282 174.32 213.85)';
const mallFloorOf=id=>({'1013':0,'1016':1,'1019':2})[id.slice(1,5)];
const floorName=n=>n===0?(english?'Ground floor':'Parter'):(n>0?'+':'')+n;
function cameraMall(){zoom=2;pan=[(525-380)*zoom,(360-385)*zoom]}
function unitName(id){return mallNames[id]||(+id.split('-')[1]>=10000?(english?'Service point — see icon':'Punkt usługowy — zobacz ikonę'):(english?'Unit without a description':'Lokal bez opisu'))}
function levelButtons(){const names=english?{2:'Dining',1:'Hall',0:'Platforms · Bus',[-1]:'Tunnels'}:{2:'Gastronomia',1:'Hala',0:'Perony · PKS',[-1]:'Tunele'};$('.levels').innerHTML=[2,1,0,-1].map(n=>`<button data-level="${n}" class="${n===level?'active':''}" aria-pressed="${n===level}">${n>0?'+':''}${n}<span>${names[n]}</span></button>`).join('');document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{level=+b.dataset.level;mallSelected=null;$('#mall-selection').textContent=english?'Choose a unit or search by name.':'Wybierz lokal lub wyszukaj nazwę.';render()})}
function selectMall(id){mallSelected=id;level=mallFloorOf(id);cameraMall();render();$('#mall-selection').textContent=unitName(id)+' · '+floorName(level)}
function mallResults(){const q=$('#mall-search').value.trim().toLocaleLowerCase('pl'),box=$('#mall-results');box.replaceChildren();if(!q)return;const matches=Object.entries(mallNames).filter(([,name])=>name.toLocaleLowerCase('pl').includes(q)).slice(0,8);if(!matches.length){box.textContent=english?'No matching units.':'Nie znaleziono lokalu.';return}for(const [id,name]of matches){const b=document.createElement('button');b.textContent=name+' · '+floorName(mallFloorOf(id));b.onclick=()=>selectMall(id);box.append(b)}}
function updateUnifiedText(){const titles=english?{'-1':'−1 · Tunnels','0':'0 · Platforms, bus terminal & Avenida','1':'+1 · Station hall & Avenida','2':'+2 · Avenida & dining'}:{'-1':'−1 · Tunele','0':'0 · Perony, dworzec autobusowy i Avenida','1':'+1 · Hala dworca i Avenida','2':'+2 · Avenida i gastronomia'};$('#levelTitle').textContent=titles[level];$('.intro').innerHTML=english?'One complex. One floor selector.<br>Platforms, terminal, shops and parking.':'Jeden kompleks. Wspólne poziomy.<br>Perony, terminal, sklepy i parkingi.';$('.notice').textContent=english?'DRAFT MAP • Shared floor alignment is approximate. Interior parking plans and connecting routes remain incomplete.':'MAPA ROBOCZA • Dopasowanie kondygnacji przybliżone. Brakuje rzutów wnętrz parkingów i zweryfikowanych połączeń.';$('#mall-search').setAttribute('aria-label',english?'Search a unit':'Szukaj lokalu');$('label[for="mall-search"]').textContent=english?'FIND A UNIT':'ZNAJDŹ LOKAL';$('.mall-hint').textContent=english?'Floor 0: bus terminal. +1: open space above it. +2: dining. Parking A–B and C–E floor plans still need verification.':'Poziom 0: terminal autobusowy. +1: otwarta przestrzeń nad nim. +2: gastronomia. Rzuty parkingów A–B i C–E wymagają uzupełnienia.';$('.source-link').textContent=english?'Official Avenida map ↗':'Oficjalny plan Avenidy ↗';const keys=$('.map-bottom').querySelectorAll(':scope > span');keys[0].innerHTML='<i class="key platform"></i>'+(english?'Platforms / units':'Perony / lokale');keys[1].innerHTML='<i class="key path"></i>'+(english?'Demo route':'Trasa demo');keys[2].textContent=english?'Hatching: incomplete plan':'Kreskowanie: brak pełnego rzutu';if(mallSelected)$('#mall-selection').textContent=unitName(mallSelected)+' · '+floorName(level)}
function zoneLabel(x,y,text,small){return txt(x,y,text,9,'#c3d6b4','text-anchor="middle" paint-order="stroke" stroke="#203027" stroke-width="2"')+(small?txt(x,y+11,small,6.5,'#a2b499','text-anchor="middle" paint-order="stroke" stroke="#203027" stroke-width="2"'):'')}
function busGeometry(){let s='';const local=(u,v)=>[537.56+40.87*u-17.74*v,384.55+8.08*u+87.78*v];const shape=pp=>`<polygon points="${pts(pp.map(p=>local(...p)))}" fill="#335453" stroke="#8bb3a3" stroke-width=".5"/>`;
// Schematic bay positions preserve the official numbering order, not measured dimensions.
for(let n=1;n<=9;n++){const v=.93-(n-1)*.095;s+=shape([[.08,v-.035],[.34,v-.06],[.37,v],[.08,v+.025]]);const p=local(.2,v);s+=txt(p[0],p[1]+1.6,n,4.5,'#e1ecdb','text-anchor="middle"');}
for(let n=10;n<=16;n++){const v=.12+(n-10)*.11;s+=shape([[.65,v-.025],[.91,v-.05],[.93,v+.01],[.67,v+.035]]);const p=local(.8,v);s+=txt(p[0],p[1]+1.6,n,4.5,'#e1ecdb','text-anchor="middle"');}
for(let n=17;n<=19;n++){const u=.42+(n-17)*.16;s+=shape([[u,.94],[u+.12,.94],[u+.12,.99],[u,.99]]);const p=local(u+.06,.975);s+=txt(p[0],p[1],n,3.5,'#e1ecdb','text-anchor="middle"');}
s+=line([local(.47,.06),local(.47,.84),local(.51,.91),local(.6,.91),local(.64,.84),local(.64,.06)],'#8aa9a0',.7);return s;}
render=function(){stationRenderer();levelButtons();updateUnifiedText();const root=svg.querySelector(':scope > g');const parking=STATION.buildings.find(b=>b.kind==='parking'),bus=STATION.buildings.find(b=>b.kind==='bus');const defs=svg.querySelector('defs');defs.insertAdjacentHTML('beforeend',`<pattern id="missing-plan" width="6" height="6" patternUnits="userSpaceOnUse" patternTransform="rotate(35)"><line x1="0" y1="0" x2="0" y2="6" stroke="#c0bd87" stroke-width=".65" opacity=".45"/></pattern><clipPath id="mall-ground-clip"><path d="M-1000 -1000H2000V2000H-1000Z M${bus.points.map(p=>p.join(' ')).join(' L')} Z" clip-rule="evenodd" fill-rule="evenodd"/></clipPath>`);
if(level>=0&&level<=2&&mallReady){const outer=document.createElementNS('http://www.w3.org/2000/svg','g');outer.setAttribute('class','unified-mall');if(level<2)outer.setAttribute('clip-path','url(#mall-ground-clip)');const wrapper=document.createElementNS('http://www.w3.org/2000/svg','g');wrapper.setAttribute('transform',mallMatrix);wrapper.setAttribute('class','mall-plan');wrapper.innerHTML=mallFloors[level];outer.append(wrapper);root.append(outer);for(const el of wrapper.querySelectorAll('[data-shop]')){const id=el.dataset.shop;el.classList.toggle('selected',id===mallSelected);el.onclick=()=>selectMall(id);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectMall(id)}}}}
if(!mallReady)$('#mall-selection').textContent=mallError?(english?'Floor plans failed to load. Refresh to retry.':'Nie udało się wczytać planów. Odśwież stronę.'):(english?'Loading floor plans…':'Wczytywanie planów…');
let overlays='';if(level===0){overlays+=`<polygon points="${pts(bus.points)}" fill="#1d3a37" stroke="#9db7a0" stroke-width="1"/>`+busGeometry()+zoneLabel(604,445,english?'BUS TERMINAL':'DWORZEC AUTOBUSOWY',english?'19 bays · schematic':'19 stanowisk · schemat');overlays+=line([[567,439],[581,442]],'#a8c5a7',.8);overlays+=zoneLabel(286,370,'P A–B',english?'2 levels · interior plan missing':'2 poziomy · brak rzutu wnętrz');}
if(level===1){overlays+=`<polygon points="${pts(bus.points)}" fill="#304b39" stroke="#9eb78d" stroke-width="1"/>`+zoneLabel(606,445,english?'OPEN SPACE':'OTWARTA PRZESTRZEŃ',english?'above the bus terminal':'nad terminalem autobusowym')+line([[565,440],[580,442]],'#a8c5a7',.8);}
if(level===2){overlays+=zoneLabel(607,445,english?'DINING':'GASTRONOMIA',english?'north wing':'skrzydło północne')+line([[565,439],[580,442]],'#a8c5a7',.8);}
if(level>=0){overlays+=`<g aria-label="Parking C D E — obrys trzech poziomów, pełne rzuty nieznane"><polygon points="${pts(parking.points)}" fill="${level===0?'none':'#263a32'}" fill-opacity=".75" stroke="#b1b085" stroke-width="1" stroke-dasharray="4 2"/><polygon points="${pts(parking.points)}" fill="url(#missing-plan)"/></g>`+zoneLabel(444,337,'P C–D–E',english?'3 levels · full plans missing':'3 poziomy · brak pełnych rzutów');}
// Keep the station hall footprint visible on its own level.
if(level===1){const h=STATION.buildings.find(b=>b.kind==='hall');overlays+=`<polygon points="${pts(h.points)}" fill="#536344" stroke="#9bb17c" stroke-width="1"/>`+zoneLabel(566,354,english?'STATION HALL':'HALA DWORCA');}
root.insertAdjacentHTML('beforeend',overlays);
};
$('#mall-search').oninput=mallResults;$('#focus-mall').onclick=()=>{cameraMall();render()};

async function loadMall(){try{const responses=await Promise.all([fetch('avenida/names.json'),...Array.from({length:3},(_,i)=>fetch('avenida/level-'+i+'.svg'))]);if(responses.some(r=>!r.ok))throw Error('Missing floor data');Object.assign(mallNames,await responses[0].json());const raw=await Promise.all(responses.slice(1).map(r=>r.text()));const colors={'#dedde0':'#293f34','#c7c8ca':'#293f34','#676767':'#809576','#d0de97':'#617c4d','#c5add4':'#697a57','#84c2cf':'#507c70','#fff':'#e6edce','#32304e':'#20352a','#2c304f':'#c5d6a9'};for(let i=0;i<3;i++){const doc=new DOMParser().parseFromString(raw[i],'image/svg+xml');if(doc.querySelector('parsererror'))throw Error('Invalid SVG');for(const e of doc.querySelectorAll('*')){if(['script','foreignObject','image'].includes(e.localName)){e.remove();continue}for(const a of [...e.attributes])if(a.name.startsWith('on')||a.name.includes('href'))e.removeAttribute(a.name);for(const a of ['fill','stroke'])if(colors[e.getAttribute(a)])e.setAttribute(a,colors[e.getAttribute(a)]);const id=e.id;if(/^p10(13|16|19)-\d+$/.test(id)){e.dataset.shop=id;e.setAttribute('class','mall-shop');e.setAttribute('role','button');e.setAttribute('tabindex','0');const name=mallNames[id]||(+id.split('-')[1]>=10000?(english?'Service point — see icon':'Punkt usługowy — zobacz ikonę'):(english?'Unit without a description':'Lokal bez opisu'));e.setAttribute('aria-label',name);const title=doc.createElementNS('http://www.w3.org/2000/svg','title');title.textContent=name;e.append(title)}e.removeAttribute('id')}mallFloors[i]=doc.documentElement.innerHTML;}mallReady=true;$('#mall-selection').textContent=english?'Choose a floor or tap a unit.':'Wybierz piętro lub dotknij lokalu.';render()}catch(e){mallError=true;$('#mall-selection').textContent=english?'Floor plans could not load. Refresh the page to retry.':'Nie udało się wczytać planów. Odśwież stronę, aby spróbować ponownie.';$('#mall-selection').setAttribute('role','alert')}}
render();loadMall();
